// The HTTP Request node emits one item per page when the API wraps its list in an
// object, and one item per element only when the body is a top-level array.
// Count pages and the records inside them separately.
const pages = $input.all();
const summarise = (key) => {
  const own = pages.filter((p) => Array.isArray(p.json[key]));
  return { pagesReceived: own.length, recordsInside: own.reduce((n, p) => n + p.json[key].length, 0) };
};
return [{ json: { products: summarise('products'), pokemon: summarise('results') } }];
